def run(scene, robot):
    box = scene.get("white box")
    pens = scene.of_kind("pen")
    if not pens:
        return
    x0, y0, x1, y1 = scene.bounds()
    gap = 2.5
    gap_y = 4.0
    max_d = max(p.d for p in pens)
    n = len(pens)
    placed = []
    for i, pen in enumerate(pens):
        tx = box.x + box.w/2 + gap + pen.w/2
        ty = box.y + (i - (n-1)/2) * (max_d + gap_y)
        if tx + pen.w/2 > x1 - 0.5:
            tx = x1 - pen.w/2 - 0.5
        if tx - pen.w/2 < x0 + 0.5:
            tx = x0 + pen.w/2 + 0.5
        if ty + pen.d/2 > y1 - 0.5:
            ty = y1 - pen.d/2 - 0.5
        if ty - pen.d/2 < y0 + 0.5:
            ty = y0 + pen.d/2 - 0.5
        avoid = [(tx, ty, pen.w + 4, pen.d + 4)]
        for o in scene.objects():
            if o.name == pen.name or o.name == box.name or o.name in placed:
                continue
            if abs(o.x - tx) < (o.w + pen.w)/2 + 3 and abs(o.y - ty) < (o.d + pen.d)/2 + 3:
                robot.move(o, *scene.free_spot(size=(o.w, o.d), clearance=3, avoid=avoid))
        cur = scene.get(pen.name)
        if not robot.can_reach(tx, ty):
            tx, ty = scene.free_spot(near=box, side="right_of", size=(pen.w, pen.d), clearance=2, avoid=avoid)
        robot.pick(cur)
        robot.place_at(tx, ty)
        placed.append(pen.name)
    robot.home()

def run(scene, robot):
    ref = scene.get("white box")
    pens = scene.of_kind("pen")
    if not pens:
        return
    gap = 2.5
    gap_y = 3.0
    n = len(pens)
    total_h = sum(p.d for p in pens) + gap_y * (n - 1) if n > 1 else pens[0].d
    y_cursor = ref.y - total_h / 2
    x0, y0, x1, y1 = scene.bounds()
    targets = []
    cur = y_cursor
    for p in pens:
        y = cur + p.d / 2
        x = ref.x + ref.w / 2 + gap + p.w / 2
        if y - p.d / 2 < y0:
            y = y0 + p.d / 2
        if y + p.d / 2 > y1:
            y = y1 - p.d / 2
        if x + p.w / 2 > x1:
            x = x1 - p.w / 2
        if x - p.w / 2 < x0:
            x = x0 + p.w / 2
        targets.append((p.name, x, y, p.w, p.d))
        cur += p.d + gap_y
    avoid = [(x, y, w + 4, d + 4) for _, x, y, w, d in targets]
    placed = []
    for name, x, y, w, d in targets:
        for o in list(scene.objects()):
            if o.name == name or o.name == ref.name or o.name in placed:
                continue
            if abs(o.x - x) < (o.w + w) / 2 + 4 and abs(o.y - y) < (o.d + d) / 2 + 4:
                robot.move(o, *scene.free_spot(size=(o.w, o.d), clearance=3, avoid=avoid))
        if not robot.can_reach(x, y):
            x, y = scene.free_spot(near=ref, side="right_of", size=(w, d), clearance=3, avoid=avoid)
        robot.move(scene.get(name), x, y)
        placed.append(name)
    robot.home()
